'use strict';

const express = require('express');
const { generateId } = require('../utils/id');
const { sendError } = require('../utils/errors');

const COLLECTION = 'players';

/**
 * Creates the Players Express router.
 * 
 * @param {object} options
 * @param {object} options.storage - Conforming storage adapter
 * @returns {import('express').Router}
 */
function createPlayersRouter({ storage }) {
  const router = express.Router();
  router.use(express.json());

  /**
   * POST /
   * Creates a new player.
   * Body: { name: string }
   */
  router.post('/', async (req, res, next) => {
    try {
      const { name } = req.body || {};

      if (!name || typeof name !== 'string' || name.trim().length === 0) {
        return sendError(res, 400, 'Player "name" is required and must be a non-empty string');
      }

      const trimmedName = name.trim();
      if (trimmedName.length > 50) {
        return sendError(res, 400, 'Player "name" cannot exceed 50 characters');
      }

      const player = {
        id: generateId('p_'),
        name: trimmedName,
        createdAt: new Date().toISOString()
      };

      await storage.set(COLLECTION, player.id, player);

      return res.status(201).json(player);
    } catch (err) {
      next(err);
    }
  });

  /**
   * GET /:id
   * Retrieves player profile by ID.
   */
  router.get('/:id', async (req, res, next) => {
    try {
      const { id } = req.params;

      if (!id || typeof id !== 'string' || id.trim().length === 0) {
        return sendError(res, 400, 'Invalid player id');
      }

      const player = await storage.get(COLLECTION, id.trim());
      if (!player) {
        return sendError(res, 404, 'Player not found');
      }

      return res.status(200).json(player);
    } catch (err) {
      next(err);
    }
  });

  return router;
}

module.exports = {
  createPlayersRouter
};
